using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class DestinationProbe {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));var p=JObject.Parse(File.ReadAllText(repo+"/SourceAssets/B5_DestinationColors/plan.json"));Physics.SyncTransforms();int n=0;var blocked=new List<object>();var missing=new List<object>();foreach(var route in p["routes"]){foreach(var xy in route["points"]){var v=new Vector3((float)xy[0],-82,(float)xy[1]);n++;var hits=Physics.OverlapCapsule(v+Vector3.up*.37f,v+Vector3.up*1.5f,.28f,~0,QueryTriggerInteraction.Ignore).Where(c=>c.transform.IsChildOf(root)&&!c.name.Contains("Floor")&&!c.name.Contains("Threshold")).ToArray();if(hits.Any())blocked.Add(new{route=(string)route["id"],p=new[]{v.x,v.z},hits=hits.Select(h=>h.name).ToArray()});if(!Physics.RaycastAll(v+Vector3.up*.30f,Vector3.down,.65f,~0,QueryTriggerInteraction.Ignore).Any(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root)))missing.Add(new{route=(string)route["id"],p=new[]{v.x,v.z}});}}
 var result=new{samples=n,blocked,missingFloor=missing};File.WriteAllText(repo+"/Docs/검수/2026-11-08_B5_DestinationColors/probe.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{samples=n,blocked=blocked.Count,missingFloor=missing.Count,firstBlocked=blocked.Take(6)};}
}
